function splitLines(text){ return String(text||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function round2(n){ return Math.round(n*100)/100; }
function scaleRecipe(text, fromServ, toServ){
  fromServ=parseFloat(fromServ)||1; toServ=parseFloat(toServ)||1;
  if(fromServ<=0) fromServ=1;
  var factor=toServ/fromServ;
  var items=splitLines(text);
  var out=items.map(function(line){
    var m=line.match(/^([\d.]+)\s*([^\s\d.]*)\s*(.*)$/);
    if(m){
      var amt=round2(parseFloat(m[1])*factor);
      var unit=m[2]||'', rest=m[3]||'';
      return amt+(unit?(' '+unit):'')+(rest?(' '+rest):'');
    }
    return line;
  });
  return {factor:factor, items:out, count:items.length};
}
var EXPORTS={splitLines:splitLines, round2:round2, scaleRecipe:scaleRecipe};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RecipeScalerForgePure = EXPORTS; }
